(async()=>{
const host=document.getElementById('nativeTimeline');
host.innerHTML=`<div class="tl-title"><span class="truck">▰</span><div><h1>บันทึกการรับน้ำมันดีเซล โรงไฟฟ้าจะนะ</h1><p>โรงไฟฟ้าจะนะ จ.สงขลา ｜ เลือกวันที่จาก Google Sheets ｜ ป้อม 1</p></div></div><div class="tl-tools"><div class="tl-tools-left"><label class="tl-date-wrap" title="เลือกวันที่"><svg class="tl-calendar-icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="2" fill="none" stroke="currentColor" stroke-width="1.8"/><path d="M7 3v4M17 3v4M3 10h18" fill="none" stroke="currentColor" stroke-width="1.8"/></svg><select id="tlDateSelect" class="tl-date-select" aria-label="เลือกวันที่ข้อมูลใน Google Sheets"></select></label></div><div class="tl-tools-right"><button id="tlRefresh" class="tl-icon-btn" title="รีเฟรชจาก Google Sheets" aria-label="รีเฟรชจาก Google Sheets"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 7v5h-5M4 17v-5h5"/><path d="M5.8 9a7 7 0 0 1 12.5-2L20 12M4 12l1.7 5A7 7 0 0 0 18.2 15"/></svg></button><button id="tlPrint" class="tl-icon-btn" title="พิมพ์กราฟ" aria-label="พิมพ์กราฟ"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 8V3h10v5M7 17H5a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><path d="M7 14h10v7H7zM17 11h1"/></svg></button><a id="tlOpenSheet" class="tl-icon-btn" href="https://docs.google.com/spreadsheets/d/1kaAYhEhTywYQEKrhFIqJDrcs4Zav0BhP97cl_sZ6Als/edit#gid=2062218599" target="_blank" rel="noopener noreferrer" title="เปิด Google Sheets" aria-label="เปิด Google Sheets"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M13 4h7v7M20 4l-9 9"/><path d="M19 14v5a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V6a1 1 0 0 1 1-1h6"/></svg></a></div></div><p id="tlNote" class="muted">กำลังอ่าน Google Sheets…</p><div id="tlKpis" class="tl-kpis"></div><div class="tl-overflow"><table class="tl-table"><thead><tr><th>ลำดับ<br><small>(ตามเวลา Unloading)</small></th><th>รอบที่</th><th>เลขทะเบียนรถ</th><th>เวลาเข้า</th><th>เวลา Unloading</th><th>เวลาออก</th><th>ปริมาณรับ<br><small>(ลิตร @86°F)</small></th><th class="tl-chart-head">ช่วงเวลาปฏิบัติงาน (เวลาเข้า – ออก ในโรงไฟฟ้า)<div id="tlAxis"></div></th></tr></thead><tbody id="tlBody"></tbody></table></div><div class="tl-legend"><b>สัญลักษณ์</b><span><i class="tl-swatch teal"></i>รถที่วิ่ง 2 รอบในวันเดียว</span><span><i class="tl-swatch orange"></i>รถที่วิ่ง 1 รอบในวันเดียว</span><span>💧 เวลา Unloading (รับน้ำมันลงถัง)</span><span id="tlReviewLegend" hidden>⚠ ลายมือต้องยืนยัน</span></div>`;
const minutes=s=>{if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(s||''))throw Error('เวลาต้องเป็น HH:mm');return +s.slice(0,2)*60 + +s.slice(3)};

function render(data,note){
if(!Array.isArray(data)||!data.length||data.length>1000)throw Error('ต้องเป็นข้อมูล 1–1,000 แถว');
const counts={},rounds={};let rows=data.map(r=>{const x={...r,plate:String(r.plate||''),province:String(r.province||''),date:String(r.date||'2026-11-16'),volume:Number(r.volume)||0};if(!x.plate)throw Error('ต้องมีทะเบียน');x.start=minutes(x.gateIn);x.finish=x.gateOut?minutes(x.gateOut):null;if(x.finish!==null&&x.finish<x.start)x.finish+=1440;const rawUnload=x.unloading?minutes(x.unloading):null;let candidate=rawUnload;if(candidate!==null&&x.finish!==null&&x.finish>=1440&&candidate<x.start)candidate+=1440;x.unload=(candidate!==null&&x.finish!==null&&candidate>=x.start&&candidate<=x.finish)?candidate:x.start;x.unloadFallback=(rawUnload===null||x.unload!==candidate);x.id=x.date+'|'+Fuel.normalize(x.plate)+'|'+Fuel.normalize(x.province);counts[x.id]=(counts[x.id]||0)+1;return x});
if(new Set(rows.map(r=>r.date)).size>1)throw Error('กรุณาเลือกข้อมูลครั้งละหนึ่งวัน');
const keys=new Set();for(const r of rows){const key=r.id+'|'+r.start;if(keys.has(key))throw Error('พบทะเบียนและเวลาเข้าซ้ำ');keys.add(key)}
rows.sort((a,b)=>a.start-b.start);for(const r of rows)r.round=rounds[r.id]=(rounds[r.id]||0)+1;
rows.sort((a,b)=>(a.unload??a.start)-(b.unload??b.start)||a.start-b.start);
const min=Math.floor(Math.min(...rows.map(r=>r.start))/60)*60,max=Math.max(min+60,Math.ceil(Math.max(...rows.map(r=>r.finish??r.start),...rows.map(r=>r.unload??r.start))/60)*60),span=max-min;
const fmt=n=>String(Math.floor(n/60)%24).padStart(2,'0')+':'+String(n%60).padStart(2,'0')+(n>=1440?' +1 วัน':'');
const qty=rows.reduce((s,r)=>s+r.volume,0),durations=rows.filter(r=>r.finish!==null).map(r=>r.finish-r.start),avg=durations.length?Math.round(durations.reduce((a,b)=>a+b)/durations.length):null;
const values=[['⟳','จำนวนรอบรวม',rows.length+' รอบ'],['◕','ปริมาณที่รับรวม',qty?qty.toLocaleString('th-TH',{maximumFractionDigits:2})+' ลิตร':'—'],['▤','ปริมาณเฉลี่ยต่อรอบ',qty?(qty/rows.length).toLocaleString('th-TH',{maximumFractionDigits:1})+' ลิตร/รอบ':'—'],['⇥','เวลาเข้าพื้นที่เร็วสุด',fmt(Math.min(...rows.map(r=>r.start)))+' น.'],['⇤','เวลาออกจากพื้นที่ช้าสุด',durations.length?fmt(Math.max(...rows.filter(r=>r.finish!==null).map(r=>r.finish)))+' น.':'—'],['◷','ระยะเวลาเฉลี่ยในพื้นที่',avg===null?'—':Math.floor(avg/60)+' ชม. '+String(avg%60).padStart(2,'0')+' นาที'],['▰','จำนวนรถบรรทุก',Object.values(counts).filter(n=>n===2).length+' คัน วิ่ง 2 รอบ / '+Object.values(counts).filter(n=>n===1).length+' คัน วิ่ง 1 รอบ']];
const kpis=document.getElementById('tlKpis');kpis.replaceChildren();for(const [icon,label,value]of values){const card=document.createElement('div');card.className='tl-kpi';const small=document.createElement('div');small.textContent=icon+'  '+label;const strong=document.createElement('strong');strong.textContent=value;card.append(small,strong);kpis.append(card)}
const axis=document.getElementById('tlAxis');axis.replaceChildren();for(let t=min;t<=max;t+=60){const tick=document.createElement('span');tick.style.left=(t-min)/span*100+'%';tick.textContent=fmt(t);axis.append(tick)}
const reviewLegend=document.getElementById('tlReviewLegend');if(reviewLegend)reviewLegend.hidden=!rows.some(r=>r.reviewRequired);
const body=document.getElementById('tlBody');body.replaceChildren();for(const [i,r]of rows.entries()){const tr=document.createElement('tr');for(const v of [i+1,r.round,r.plate+(r.reviewRequired?' ⚠':''),r.gateIn,r.unloadFallback?r.gateIn:r.unloading,r.gateOut||'—',r.volume>0?r.volume.toLocaleString('th-TH',{maximumFractionDigits:2}):'—']){const td=document.createElement('td');td.textContent=v;if(r.reviewRequired)td.title=r.sourceNote||'ต้องตรวจทาน';tr.append(td)}const cell=document.createElement('td');cell.className='tl-chart';cell.style.setProperty('--step',60/span*100+'%');const bar=document.createElement('div');bar.className='tl-bar '+(counts[r.id]===2?'teal':'orange');bar.style.left=(r.start-min)/span*100+'%';bar.style.width=Math.max(.2,((r.finish??r.start)-r.start)/span*100)+'%';bar.title=r.plate+' เที่ยว '+r.round+' | '+r.gateIn+'–'+(r.gateOut||'ยังไม่ออก');cell.append(bar);if(r.unload!==null){const dot=document.createElementNS('http://www.w3.org/2000/svg','svg');dot.setAttribute('viewBox','0 0 16 20');dot.setAttribute('aria-label','จุดเวลารับน้ำมันลงถัง');dot.classList.add('tl-drop');dot.style.left=(r.unload-min)/span*100+'%';dot.setAttribute('role','img');const dropPath=document.createElementNS('http://www.w3.org/2000/svg','path');dropPath.setAttribute('d','M8 1 C6 4 2 8 2 12 A6 6 0 0 0 14 12 C14 8 10 4 8 1 Z');dot.append(dropPath);const dropTitle=document.createElementNS('http://www.w3.org/2000/svg','title');dropTitle.textContent=r.unloadFallback?'Unloading ใช้เวลาเข้าแทน ('+r.gateIn+')':'Unloading '+r.unloading;dot.append(dropTitle);cell.append(dot)}tr.append(cell);body.append(tr)}
document.getElementById('tlNote').textContent=note||'ข้อมูลจาก Google Sheets';
}
document.getElementById('tlPrint').onclick=()=>window.print();
let sheetRows=[];const select=document.getElementById('tlDateSelect');const refresh=document.getElementById('tlRefresh');
function showDay(){const chosen=sheetRows.filter(r=>r.date===select.value);render(chosen,'อ่านจาก Google Sheets · '+new Date().toLocaleTimeString('th-TH',{timeZone:'Asia/Bangkok'})+' น.'+(chosen.some(r=>r.reviewRequired)?' · ⚠ มีรายการที่ต้องยืนยันทะเบียน':''));host.querySelector('.tl-title p').textContent='โรงไฟฟ้าจะนะ จ.สงขลา ｜ วันที่ '+new Date(select.value+'T12:00:00+07:00').toLocaleDateString('th-TH',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Bangkok'})+' ｜ ป้อม 1';}
async function refreshSheet(){refresh.disabled=true;document.getElementById('tlNote').textContent='กำลังอ่าน Google Sheets…';try{const result=await window.FuelSheet.load();const days=[...new Set(result.map(r=>r.date))].sort();if(!days.length)throw Error('ชีตยังไม่มีรายการรถ');const previous=select.value;sheetRows=result;select.replaceChildren(...days.map(day=>{const o=document.createElement('option');o.value=day;o.textContent=day;return o}));select.value=days.includes(previous)?previous:days.at(-1);showDay()}catch(e){document.getElementById('tlNote').textContent='อ่านชีตไม่สำเร็จ: '+e.message+(sheetRows.length?' · กราฟที่เห็นเป็นข้อมูลจากการโหลดครั้งก่อน':'')}finally{refresh.disabled=false}}
select.onchange=showDay;refresh.onclick=refreshSheet;await refreshSheet();
})();
